  function order(no,customer,phone,type,status,total,paid,paymentStatus,expire,remark,items,payments) { return { no, id:"01JY"+no.replace(/\W/g,"")+"4M8R2H6C9V5B", customer, phone, customerId:"CU-"+no.slice(3), type, status, total, paid, paymentStatus, expire, remark, items, payments, createdAt:"2026-06-17 09:58", updatedAt:"2026-06-18 10:18", branch:"Plateau Central" }; }
